import{_ as a,o as t,c as r,j as o}from"./chunks/framework.DsyGq6Zh.js";const u=JSON.parse('{"title":"The Race Track and the Pit Stop","description":"A configurable human–AI governance pattern for consequence-aware review, commissioning, and recoverable decisions.","frontmatter":{"title":"The Race Track and the Pit Stop","description":"A configurable human–AI governance pattern for consequence-aware review, commissioning, and recoverable decisions."},"headers":[],"relativePath":"research/systems/race-track-pit-stop.md","filePath":"research/systems/race-track-pit-stop.md"}'),i={name:"research/systems/race-track-pit-stop.md"};function s(n,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="the-race-track-and-the-pit-stop" tabindex="-1">The Race Track and the Pit Stop <a class="header-anchor" href="#the-race-track-and-the-pit-stop" aria-label="Permalink to &quot;The Race Track and the Pit Stop&quot;">​</a></h1><p><em>Working architectural proposal · November 2026</em></p><p>A system that asks a person to approve everything does not scale. A system that decides everything itself may be fast and catastrophically wrong. I use <strong>Race Track / Pit Stop</strong> as a plain-language model for the space between these extremes.</p><p>The <a href="https://github.com/kaw393939/ordo/blob/main/agentic-appliance/patterns/race-track-pit-stop.md" target="_blank" rel="noreferrer">Ordo pattern</a> describes a Race Track for bounded routine work and a Pit Stop for consequential, disputed, or insufficiently supported work. The idea is not just a visual workflow. It is a proposal for governing decision authority at runtime.</p><h2 id="what-changes-with-self-describing-sensors" tabindex="-1">What changes with self-describing sensors <a class="header-anchor" href="#what-changes-with-self-describing-sensors" aria-label="Permalink to &quot;What changes with self-describing sensors&quot;">​</a></h2><p>A sensor should be an independent, discoverable component. It might read email metadata, recognize faces in a film, detect contradictory claims, inspect a contract, or report GPU memory use. It should describe <em>what it can observe</em>, input/output contracts, limitations, resource costs, configurable parameters, and version.</p><p>The orchestration system should not need to know every future sensor capability in advance. Sensors produce typed <strong>observations</strong>; a separate analysis layer constructs interpretations; a recommendation layer proposes next actions. An independent policy layer determines authority.</p><p>That distinction makes the architecture extensible without confusing <em>observation</em>, <em>belief</em>, <em>authorization</em>, and <em>execution</em>.</p><h2 id="consequences-drive-routing" tabindex="-1">Consequences drive routing <a class="header-anchor" href="#consequences-drive-routing" aria-label="Permalink to &quot;Consequences drive routing&quot;">​</a></h2><p>Consider three statements extracted from correspondence:</p><ol><li>A person sent a message on Tuesday. The header can be checked automatically.</li><li>A person said the board approved a transaction. The statement is attributable, but does not itself prove approval.</li><li>The company is authorized to transfer funds. This has significant consequences and requires stronger evidence and potentially an authorized human decision.</li></ol><p>The same model may be equally confident about all three strings. They do not deserve the same routing policy.</p><p>Risk estimation needs expected error, severity, uncertainty in measurement, reversibility, and propagation to dependent decisions. Authorization is a separate hard constraint: high confidence does not give an agent permission to send money or publish confidential information.</p><h2 id="commissioning-through-examples" tabindex="-1">Commissioning through examples <a class="header-anchor" href="#commissioning-through-examples" aria-label="Permalink to &quot;Commissioning through examples&quot;">​</a></h2><p>Initially, operators may review many proposed classifications. Every accepted correction becomes a <strong>case decision</strong>, never an implicit permanent authorization. The system can then propose a scoped <strong>policy decision</strong> (for example, automatically accept a category of unambiguous source-header relationships) and test it against prior decisions.</p><p>A policy should record who authorized it, its applicable domain, evidence requirements, effective version, rollback procedure, and independent evaluations. Approval history should be reproducible rather than reconstructed by a model after the fact.</p><p>A human or authorized AI delegate can review a case within its role. Delegating evaluation does not necessarily delegate approval authority.</p><h2 id="progressive-disclosure" tabindex="-1">Progressive disclosure <a class="header-anchor" href="#progressive-disclosure" aria-label="Permalink to &quot;Progressive disclosure&quot;">​</a></h2><p>An operator&#39;s default view should show:</p><p><strong>What needs deciding? Why now? What could go wrong? What is recommended?</strong></p><p>A second level reveals alternatives, summary statistics, disagreements, and relevant prior decisions. An optional evidence view reveals raw source passages, full sensor readings, model outputs, and traces.</p><p>The aim is to make review comprehensible without hiding evidence from people who need it.</p><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><p>Test three routing policies on held-out labeled cases: (a) review everything, (b) fixed confidence threshold, and (c) consequence-aware, progressively commissioned routing. Measure review minutes, consequential errors that escape review, missed escalations, decision latency, and policy drift. Evaluate explicitly under changes in source quality and reviewer workload.</p><h3 id="research-precedents" tabindex="-1">Research precedents <a class="header-anchor" href="#research-precedents" aria-label="Permalink to &quot;Research precedents&quot;">​</a></h3><p>This is not a claim to have invented intelligent interruptions. <a href="https://www.microsoft.com/en-us/research/people/horvitz/publications/" target="_blank" rel="noreferrer">Horvitz et al. (1999)</a> studied attention-sensitive alerting. <a href="https://digitalcommons.njit.edu/fac_pubs/6913/" target="_blank" rel="noreferrer">Grandhi and Jones (2015)</a> found that additional context about an interruption improves people&#39;s ability to predict its value.</p><p>The proposed contribution would be an evaluated mechanism for <strong>commissioning and revising risk-aware human–AI decision policies with provenance</strong>, not the idea of an interruption gate itself.</p><p><a href="./">Research series</a> · <a href="./dissertation-proposal">Dissertation proposal</a></p>',28)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
